public final class Fib {
    private Fib() {}

    // BUG: naive double recursion recomputes the same sub-values
    // exponentially many times - unusably slow once n is in the low 40s.
    public static long of(long n) {
        if (n < 2) return n;
        return of(n - 1) + of(n - 2);
    }
}

