public final class FibTest {
    public static void main(String[] args) {
        checkSmallValues();
        checkLargeIsFastAndCorrect();
        System.out.println("all tests passed");
    }

    static void checkSmallValues() {
        check(0, Fib.of(0));
        check(1, Fib.of(1));
        check(1, Fib.of(2));
        check(5, Fib.of(5));
        check(55, Fib.of(10));
    }

    static void checkLargeIsFastAndCorrect() {
        long start = System.nanoTime();
        long result = Fib.of(45);
        double elapsedMs = (System.nanoTime() - start) / 1e6;

        check(1134903170L, result);
        if (elapsedMs >= 2500) {
            throw new AssertionError(String.format(
                "Fib.of(45) took %.1fms - expected a memoized/linear-time implementation, "
                    + "not naive exponential double recursion", elapsedMs));
        }
    }

    static void check(long expected, long got) {
        if (expected != got) {
            throw new AssertionError("expected " + expected + " but got " + got);
        }
    }
}

