import java.util.HashMap;
import java.util.Map;

public final class Fib {
    private Fib() {}

    public static long of(long n) {
        return of(n, new HashMap<>());
    }

    private static long of(long n, Map<Long, Long> cache) {
        if (n < 2) return n;
        Long cached = cache.get(n);
        if (cached != null) return cached;
        long result = of(n - 1, cache) + of(n - 2, cache);
        cache.put(n, result);
        return result;
    }
}

