public final class Fib {
    private Fib() {}

    // Correct values but still exponential: the "helper" is just the same
    // naive double recursion renamed.
    private static long rec(long n) {
        if (n < 2) return n;
        return rec(n - 1) + rec(n - 2);
    }

    public static long of(long n) {
        return rec(n);
    }
}
